entries.badExample:
switch (command) {
case START: start_device();
case STOP: stop_device(); break;
}

entries.goodExample:
/* 独立动作在分支末尾结束 */
switch (command) {
case START: start_device(); break;
case STOP: stop_device(); break;
}

/* 重启需要先停止，再共用启动动作；C23 之前适用于 GCC 和 Clang */
switch (command) {
case RESTART:
    stop_device();
    __attribute__((fallthrough));
case START:
    start_device();
    break;
}

/* C23 起，有意贯穿的分支可使用标准属性 */
switch (command) {
case RESTART:
    stop_device();
    [[fallthrough]];
case START:
    start_device();
    break;
}

entries.badExample:
void clear(int values[]) {
    size_t count = sizeof(values) / sizeof(values[0]);
    for (size_t i = 0; i < count; ++i) values[i] = 0;
}

entries.goodExample:
void clear(int *values, size_t count) {
    for (size_t i = 0; i < count; ++i) values[i] = 0;
}
/* 调用方仍持有数组 */
int values[8];
clear(values, sizeof(values) / sizeof(values[0]));

